-- ============================================================
-- DATABASE: NO NAME MILK TEA SHOP
-- PostgreSQL 15+
-- Based on: Bao_cao_GK_Nhom_No_Name.pdf, section 6 (pages 50-61)
-- 24 tables: 20 report tables + 4 operational support tables
--
-- Run:
--   1) CREATE DATABASE no_name_shop;
--   2) Connect to no_name_shop
--   3) Execute this file in pgAdmin / psql
--
-- IMPORTANT:
--   Password hashes must be generated by the application using
--   Argon2id or bcrypt. Never store plain-text passwords.
-- ============================================================

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- -------------------------
-- 1. DROP OBJECTS (optional)
-- -------------------------
-- Uncomment the next line only when you intentionally want to reset
-- the whole schema and delete all existing data.
-- DROP SCHEMA public CASCADE; CREATE SCHEMA public;

-- -------------------------
-- 2. MASTER / AUTH TABLES
-- -------------------------

CREATE TABLE roles (
    role_id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    role_name     VARCHAR(50) NOT NULL UNIQUE,
    description   TEXT,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_roles_name CHECK (role_name IN
        ('Owner', 'Manager', 'Order', 'Cashier', 'Barista'))
);

CREATE TABLE staff (
    staff_id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name     VARCHAR(100) NOT NULL,
    phone         VARCHAR(15) NOT NULL UNIQUE,
    dob           DATE,
    address       TEXT,
    email         VARCHAR(100) UNIQUE,
    hire_date     DATE NOT NULL DEFAULT CURRENT_DATE,
    status        VARCHAR(30) NOT NULL DEFAULT 'Đang làm việc',
    created_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_staff_status CHECK (status IN
        ('Đang làm việc', 'Tạm nghỉ', 'Nghỉ việc')),
    CONSTRAINT ck_staff_dob CHECK (dob IS NULL OR dob <= CURRENT_DATE),
    CONSTRAINT ck_staff_hire_date CHECK (hire_date <= CURRENT_DATE)
);

CREATE TABLE users (
    user_id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    staff_id       BIGINT NOT NULL UNIQUE REFERENCES staff(staff_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    role_id        BIGINT NOT NULL REFERENCES roles(role_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    username       VARCHAR(50) NOT NULL UNIQUE,
    password_hash  VARCHAR(255) NOT NULL,
    status         VARCHAR(20) NOT NULL DEFAULT 'Active',
    failed_attempts INTEGER NOT NULL DEFAULT 0,
    locked_until   TIMESTAMPTZ,
    last_login     TIMESTAMPTZ,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_users_status CHECK (status IN ('Active','Inactive','Locked')),
    CONSTRAINT ck_users_failed_attempts CHECK (failed_attempts >= 0),
    CONSTRAINT ck_users_username CHECK (length(trim(username)) >= 3)
);

CREATE TABLE user_sessions (
    session_id     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id        BIGINT NOT NULL REFERENCES users(user_id)
                   ON UPDATE CASCADE ON DELETE CASCADE,
    token_hash     VARCHAR(255) NOT NULL UNIQUE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at     TIMESTAMPTZ NOT NULL,
    revoked_at     TIMESTAMPTZ,
    ip_address     INET,
    user_agent     TEXT,
    CONSTRAINT ck_session_expiry CHECK (expires_at > created_at)
);

-- -------------------------
-- 3. STAFF / SHIFT TABLES
-- -------------------------

CREATE TABLE shifts (
    shift_id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    shift_name     VARCHAR(50) NOT NULL UNIQUE,
    start_time     TIME NOT NULL,
    end_time       TIME NOT NULL,
    description    TEXT,
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT ck_shift_time CHECK (end_time > start_time)
);

-- Each row represents one employee assigned to a shift on a work date,
-- with actual check-in / check-out times.
CREATE TABLE attendances (
    attendance_id  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    staff_id       BIGINT NOT NULL REFERENCES staff(staff_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    shift_id       BIGINT NOT NULL REFERENCES shifts(shift_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    work_date      DATE NOT NULL DEFAULT CURRENT_DATE,
    check_in       TIMESTAMPTZ,
    check_out      TIMESTAMPTZ,
    note           TEXT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_attendance_staff_shift_date
        UNIQUE (staff_id, shift_id, work_date),
    CONSTRAINT ck_attendance_times
        CHECK (check_out IS NULL OR (check_in IS NOT NULL AND check_out >= check_in))
);

-- -------------------------
-- 4. CUSTOMER / CRM TABLES
-- -------------------------

CREATE TABLE customers (
    customer_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name      VARCHAR(100) NOT NULL,
    phone          VARCHAR(15) NOT NULL UNIQUE,
    points         INTEGER NOT NULL DEFAULT 0,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_customer_points CHECK (points >= 0)
);

CREATE TABLE loyalty_transactions (
    loyalty_transaction_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id    BIGINT NOT NULL REFERENCES customers(customer_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    order_id       BIGINT,
    transaction_type VARCHAR(20) NOT NULL,
    points_change INTEGER NOT NULL,
    description    TEXT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by     BIGINT REFERENCES staff(staff_id)
                   ON UPDATE CASCADE ON DELETE SET NULL,
    CONSTRAINT ck_loyalty_type CHECK
        (transaction_type IN ('EARN','REDEEM','ADJUST')),
    CONSTRAINT ck_loyalty_nonzero CHECK (points_change <> 0)
);

-- -------------------------
-- 5. MENU TABLES
-- -------------------------

CREATE TABLE categories (
    category_id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_name  VARCHAR(100) NOT NULL UNIQUE,
    description    TEXT,
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE products (
    product_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_id    BIGINT NOT NULL REFERENCES categories(category_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    product_name   VARCHAR(150) NOT NULL,
    base_price     NUMERIC(12,2) NOT NULL,
    description    TEXT,
    image_url      VARCHAR(500),
    status         VARCHAR(30) NOT NULL DEFAULT 'Còn hàng',
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_product_price CHECK (base_price >= 0),
    CONSTRAINT ck_product_status CHECK (status IN ('Còn hàng','Hết hàng','Ngừng bán'))
);

CREATE TABLE sizes (
    size_id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    size_name      VARCHAR(10) NOT NULL UNIQUE,
    extra_price    NUMERIC(12,2) NOT NULL DEFAULT 0,
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT ck_size_extra_price CHECK (extra_price >= 0)
);

CREATE TABLE toppings (
    topping_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    topping_name   VARCHAR(100) NOT NULL UNIQUE,
    price          NUMERIC(12,2) NOT NULL,
    status         VARCHAR(30) NOT NULL DEFAULT 'Còn hàng',
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_topping_price CHECK (price >= 0),
    CONSTRAINT ck_topping_status CHECK (status IN ('Còn hàng','Hết hàng','Ngừng bán'))
);

CREATE TABLE promotions (
    promotion_id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    promo_code     VARCHAR(30) NOT NULL UNIQUE,
    promo_name     VARCHAR(150) NOT NULL,
    min_order_value NUMERIC(12,2) NOT NULL DEFAULT 0,
    discount_type  VARCHAR(20) NOT NULL DEFAULT 'FIXED',
    discount_value NUMERIC(12,2) NOT NULL,
    max_discount   NUMERIC(12,2),
    start_date     DATE NOT NULL,
    end_date       DATE NOT NULL,
    usage_limit    INTEGER,
    used_count     INTEGER NOT NULL DEFAULT 0,
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_promo_min_order CHECK (min_order_value >= 0),
    CONSTRAINT ck_promo_type CHECK (discount_type IN ('PERCENT','FIXED')),
    CONSTRAINT ck_promo_value CHECK
        ((discount_type = 'PERCENT' AND discount_value > 0 AND discount_value <= 100)
         OR (discount_type = 'FIXED' AND discount_value > 0)),
    CONSTRAINT ck_promo_dates CHECK (end_date >= start_date),
    CONSTRAINT ck_promo_max_discount CHECK (max_discount IS NULL OR max_discount >= 0),
    CONSTRAINT ck_promo_usage CHECK
        ((usage_limit IS NULL OR usage_limit >= 0) AND used_count >= 0)
);

-- -------------------------
-- 6. POS / ORDER TABLES
-- -------------------------

CREATE TABLE orders (
    order_id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    staff_id        BIGINT NOT NULL REFERENCES staff(staff_id)
                    ON UPDATE CASCADE ON DELETE RESTRICT,
    customer_id     BIGINT REFERENCES customers(customer_id)
                    ON UPDATE CASCADE ON DELETE SET NULL,
    promotion_id    BIGINT REFERENCES promotions(promotion_id)
                    ON UPDATE CASCADE ON DELETE SET NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    subtotal_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
    discount_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
    points_redeemed INTEGER NOT NULL DEFAULT 0,
    total_amount    NUMERIC(12,2) NOT NULL DEFAULT 0,
    order_status    VARCHAR(30) NOT NULL DEFAULT 'Chờ thanh toán',
    note            TEXT,
    CONSTRAINT ck_order_amounts CHECK
        (subtotal_amount >= 0 AND discount_amount >= 0 AND total_amount >= 0),
    CONSTRAINT ck_order_points_redeemed CHECK (points_redeemed >= 0),
    CONSTRAINT ck_order_status CHECK (order_status IN
        ('Chờ thanh toán','Đã thanh toán','Đang pha chế','Đã xong','Đã hủy'))
);

CREATE TABLE order_details (
    order_detail_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id        BIGINT NOT NULL REFERENCES orders(order_id)
                    ON UPDATE CASCADE ON DELETE CASCADE,
    product_id      BIGINT NOT NULL REFERENCES products(product_id)
                    ON UPDATE CASCADE ON DELETE RESTRICT,
    size_id         BIGINT NOT NULL REFERENCES sizes(size_id)
                    ON UPDATE CASCADE ON DELETE RESTRICT,
    product_name_snapshot VARCHAR(150) NOT NULL,
    base_price_snapshot NUMERIC(12,2) NOT NULL,
    size_name_snapshot VARCHAR(10) NOT NULL,
    size_price_snapshot NUMERIC(12,2) NOT NULL DEFAULT 0,
    sugar_level     VARCHAR(10) NOT NULL DEFAULT '100%',
    ice_level       VARCHAR(10) NOT NULL DEFAULT '100%',
    quantity        INTEGER NOT NULL DEFAULT 1,
    item_note       VARCHAR(255),
    line_total      NUMERIC(12,2) NOT NULL,
    CONSTRAINT ck_detail_sugar CHECK (sugar_level IN ('0%','30%','50%','70%','100%')),
    CONSTRAINT ck_detail_ice CHECK (ice_level IN ('0%','30%','50%','70%','100%')),
    CONSTRAINT ck_detail_quantity CHECK (quantity > 0),
    CONSTRAINT ck_detail_prices CHECK
        (base_price_snapshot >= 0 AND size_price_snapshot >= 0 AND line_total >= 0)
);

CREATE TABLE order_detail_toppings (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_detail_id BIGINT NOT NULL REFERENCES order_details(order_detail_id)
                    ON UPDATE CASCADE ON DELETE CASCADE,
    topping_id      BIGINT NOT NULL REFERENCES toppings(topping_id)
                    ON UPDATE CASCADE ON DELETE RESTRICT,
    topping_name_snapshot VARCHAR(100) NOT NULL,
    quantity        INTEGER NOT NULL DEFAULT 1,
    price_snapshot  NUMERIC(12,2) NOT NULL,
    CONSTRAINT uq_detail_topping UNIQUE (order_detail_id, topping_id),
    CONSTRAINT ck_detail_topping_quantity CHECK (quantity > 0),
    CONSTRAINT ck_detail_topping_price CHECK (price_snapshot >= 0)
);

CREATE TABLE payments (
    payment_id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id        BIGINT NOT NULL UNIQUE REFERENCES orders(order_id)
                    ON UPDATE CASCADE ON DELETE RESTRICT,
    payment_method  VARCHAR(30) NOT NULL DEFAULT 'Tiền mặt',
    amount_paid     NUMERIC(12,2) NOT NULL,
    cash_received   NUMERIC(12,2),
    change_amount   NUMERIC(12,2) NOT NULL DEFAULT 0,
    paid_at         TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    transaction_ref VARCHAR(150),
    payment_status  VARCHAR(20) NOT NULL DEFAULT 'SUCCESS',
    CONSTRAINT ck_payment_method CHECK
        (payment_method IN ('Tiền mặt','Chuyển khoản QR')),
    CONSTRAINT ck_payment_amount CHECK (amount_paid >= 0),
    CONSTRAINT ck_payment_cash CHECK
        ((cash_received IS NULL OR cash_received >= amount_paid)
         AND change_amount >= 0),
    CONSTRAINT ck_payment_status CHECK (payment_status IN ('SUCCESS','REFUNDED'))
);

-- -------------------------
-- 7. INVENTORY / RECIPE TABLES
-- -------------------------

CREATE TABLE ingredients (
    ingredient_id  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ingredient_name VARCHAR(100) NOT NULL UNIQUE,
    unit           VARCHAR(20) NOT NULL,
    stock_quantity NUMERIC(14,3) NOT NULL DEFAULT 0,
    min_threshold  NUMERIC(14,3) NOT NULL DEFAULT 0,
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_ingredient_stock CHECK (stock_quantity >= 0),
    CONSTRAINT ck_ingredient_threshold CHECK (min_threshold >= 0)
);

-- A recipe row belongs to exactly one product+size OR one topping.
-- For a drink recipe: product_id and size_id are filled, topping_id is NULL.
-- For a topping recipe: topping_id is filled, product_id and size_id are NULL.
CREATE TABLE recipes (
    recipe_id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    product_id     BIGINT REFERENCES products(product_id)
                   ON UPDATE CASCADE ON DELETE CASCADE,
    size_id        BIGINT REFERENCES sizes(size_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    topping_id     BIGINT REFERENCES toppings(topping_id)
                   ON UPDATE CASCADE ON DELETE CASCADE,
    ingredient_id  BIGINT NOT NULL REFERENCES ingredients(ingredient_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    quantity_required NUMERIC(14,3) NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_recipe_target CHECK (
        (product_id IS NOT NULL AND size_id IS NOT NULL AND topping_id IS NULL)
        OR
        (product_id IS NULL AND size_id IS NULL AND topping_id IS NOT NULL)
    ),
    CONSTRAINT ck_recipe_quantity CHECK (quantity_required > 0)
);

CREATE UNIQUE INDEX uq_recipe_product_size_ingredient
    ON recipes(product_id, size_id, ingredient_id)
    WHERE product_id IS NOT NULL;

CREATE UNIQUE INDEX uq_recipe_topping_ingredient
    ON recipes(topping_id, ingredient_id)
    WHERE topping_id IS NOT NULL;

CREATE TABLE stock_imports (
    import_id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    staff_id       BIGINT NOT NULL REFERENCES staff(staff_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    voucher_type   VARCHAR(20) NOT NULL DEFAULT 'IMPORT',
    total_cost     NUMERIC(14,2) NOT NULL DEFAULT 0,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status         VARCHAR(30) NOT NULL DEFAULT 'Nháp',
    note           TEXT,
    posted_at      TIMESTAMPTZ,
    CONSTRAINT ck_stock_voucher_type CHECK (voucher_type IN ('IMPORT','WASTE')),
    CONSTRAINT ck_stock_total_cost CHECK (total_cost >= 0),
    CONSTRAINT ck_stock_status CHECK (status IN ('Nháp','Hoàn thành','Đã hủy'))
);

CREATE TABLE stock_import_details (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    import_id      BIGINT NOT NULL REFERENCES stock_imports(import_id)
                   ON UPDATE CASCADE ON DELETE CASCADE,
    ingredient_id  BIGINT NOT NULL REFERENCES ingredients(ingredient_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    quantity       NUMERIC(14,3) NOT NULL,
    unit_price     NUMERIC(14,2) NOT NULL DEFAULT 0,
    CONSTRAINT uq_stock_import_ingredient UNIQUE (import_id, ingredient_id),
    CONSTRAINT ck_stock_detail_quantity CHECK (quantity > 0),
    CONSTRAINT ck_stock_detail_price CHECK (unit_price >= 0)
);

-- Complete inventory ledger: IMPORT / WASTE / SALE / ADJUSTMENT
CREATE TABLE stock_movements (
    stock_movement_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ingredient_id  BIGINT NOT NULL REFERENCES ingredients(ingredient_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    movement_type  VARCHAR(20) NOT NULL,
    quantity_change NUMERIC(14,3) NOT NULL,
    reference_type VARCHAR(30),
    reference_id   BIGINT,
    note           TEXT,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_stock_movement_type CHECK
        (movement_type IN ('IMPORT','WASTE','SALE','ADJUSTMENT')),
    CONSTRAINT ck_stock_movement_nonzero CHECK (quantity_change <> 0)
);

-- -------------------------
-- 8. APPROVAL / AUDIT TABLES
-- -------------------------

CREATE TABLE approval_requests (
    request_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_by     BIGINT NOT NULL REFERENCES staff(staff_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    approved_by    BIGINT REFERENCES staff(staff_id)
                   ON UPDATE CASCADE ON DELETE RESTRICT,
    request_type   VARCHAR(50) NOT NULL,
    reference_id   BIGINT,
    content        TEXT NOT NULL,
    status         VARCHAR(30) NOT NULL DEFAULT 'Chờ duyệt',
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolved_at    TIMESTAMPTZ,
    resolution_note TEXT,
    CONSTRAINT ck_approval_type CHECK
        (request_type IN ('Hủy hóa đơn','Nhập hàng lớn','Sửa giá','Khác')),
    CONSTRAINT ck_approval_status CHECK
        (status IN ('Chờ duyệt','Đã duyệt','Từ chối')),
    CONSTRAINT ck_approval_resolution CHECK
        ((status = 'Chờ duyệt' AND resolved_at IS NULL)
         OR (status <> 'Chờ duyệt' AND resolved_at IS NOT NULL))
);

CREATE TABLE audit_logs (
    audit_id       BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id        BIGINT REFERENCES users(user_id)
                   ON UPDATE CASCADE ON DELETE SET NULL,
    action         VARCHAR(100) NOT NULL,
    table_name     VARCHAR(100),
    record_id      BIGINT,
    old_data       JSONB,
    new_data       JSONB,
    ip_address     INET,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Add order reference to loyalty history after orders exists.
ALTER TABLE loyalty_transactions
    ADD CONSTRAINT fk_loyalty_order
    FOREIGN KEY (order_id) REFERENCES orders(order_id)
    ON UPDATE CASCADE ON DELETE SET NULL;

-- -------------------------
-- 9. INDEXES
-- -------------------------

CREATE INDEX idx_users_role ON users(role_id);
CREATE INDEX idx_users_status ON users(status);
CREATE INDEX idx_sessions_user_expiry ON user_sessions(user_id, expires_at);
CREATE INDEX idx_attendance_date ON attendances(work_date);
CREATE INDEX idx_orders_created_at ON orders(created_at);
CREATE INDEX idx_orders_status ON orders(order_status);
CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE INDEX idx_order_details_order ON order_details(order_id);
CREATE INDEX idx_order_details_product ON order_details(product_id);
CREATE INDEX idx_payments_paid_at ON payments(paid_at);
CREATE INDEX idx_ingredients_low_stock ON ingredients(stock_quantity, min_threshold);
CREATE INDEX idx_stock_imports_created ON stock_imports(created_at);
CREATE INDEX idx_stock_movements_ingredient_date
    ON stock_movements(ingredient_id, created_at);
CREATE INDEX idx_approval_status ON approval_requests(status, created_at);
CREATE INDEX idx_loyalty_customer_date
    ON loyalty_transactions(customer_id, created_at);

-- -------------------------
-- 10. COMMON UPDATED_AT TRIGGER
-- -------------------------

CREATE OR REPLACE FUNCTION fn_set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_staff_updated
BEFORE UPDATE ON staff
FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();

CREATE TRIGGER trg_users_updated
BEFORE UPDATE ON users
FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();

CREATE TRIGGER trg_customers_updated
BEFORE UPDATE ON customers
FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();

CREATE TRIGGER trg_products_updated
BEFORE UPDATE ON products
FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();

CREATE TRIGGER trg_ingredients_updated
BEFORE UPDATE ON ingredients
FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();

-- -------------------------
-- 11. SNAPSHOT PRICES ON ORDER DETAIL
-- -------------------------

CREATE OR REPLACE FUNCTION fn_fill_order_detail_snapshot()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
    v_product products%ROWTYPE;
    v_size sizes%ROWTYPE;
BEGIN
    SELECT * INTO v_product
    FROM products WHERE product_id = NEW.product_id AND status = 'Còn hàng';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Sản phẩm không tồn tại hoặc đang hết/ngừng bán';
    END IF;

    SELECT * INTO v_size
    FROM sizes WHERE size_id = NEW.size_id AND is_active = TRUE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Size không tồn tại hoặc đã ngừng áp dụng';
    END IF;

    NEW.product_name_snapshot := v_product.product_name;
    NEW.base_price_snapshot := v_product.base_price;
    NEW.size_name_snapshot := v_size.size_name;
    NEW.size_price_snapshot := v_size.extra_price;
    -- Initial line total before any topping is attached.
    NEW.line_total := (v_product.base_price + v_size.extra_price) * NEW.quantity;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_order_detail_snapshot
BEFORE INSERT ON order_details
FOR EACH ROW EXECUTE FUNCTION fn_fill_order_detail_snapshot();

-- -------------------------
-- 12. RECALCULATE ORDER TOTAL
-- -------------------------

CREATE OR REPLACE FUNCTION fn_recalculate_order(p_order_id BIGINT)
RETURNS VOID LANGUAGE plpgsql AS $$
DECLARE
    v_subtotal NUMERIC(12,2);
    v_discount NUMERIC(12,2);
BEGIN
    SELECT COALESCE(SUM(line_total),0)
      INTO v_subtotal
      FROM order_details
     WHERE order_id = p_order_id;

    SELECT discount_amount INTO v_discount
      FROM orders
     WHERE order_id = p_order_id
     FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Không tìm thấy order %', p_order_id;
    END IF;

    UPDATE orders
       SET subtotal_amount = v_subtotal,
           total_amount = GREATEST(v_subtotal - COALESCE(v_discount,0),0)
     WHERE order_id = p_order_id
       AND order_status = 'Chờ thanh toán';
END;
$$;

CREATE OR REPLACE FUNCTION fn_order_detail_recalculate_trigger()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        PERFORM fn_recalculate_order(OLD.order_id);
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        PERFORM fn_recalculate_order(NEW.order_id);
        IF OLD.order_id <> NEW.order_id THEN
            PERFORM fn_recalculate_order(OLD.order_id);
        END IF;
        RETURN NEW;
    ELSE
        PERFORM fn_recalculate_order(NEW.order_id);
        RETURN NEW;
    END IF;
END;
$$;

CREATE TRIGGER trg_order_detail_recalculate
AFTER INSERT OR UPDATE OR DELETE ON order_details
FOR EACH ROW EXECUTE FUNCTION fn_order_detail_recalculate_trigger();

-- -------------------------
-- 13. ADD TOPPING TO ORDER DETAIL
-- -------------------------

CREATE OR REPLACE FUNCTION fn_fill_order_topping_snapshot()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
    v_topping toppings%ROWTYPE;
BEGIN
    SELECT * INTO v_topping
      FROM toppings
     WHERE topping_id = NEW.topping_id AND status = 'Còn hàng';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Topping không tồn tại hoặc đang hết/ngừng bán';
    END IF;

    NEW.topping_name_snapshot := v_topping.topping_name;
    NEW.price_snapshot := v_topping.price;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_order_topping_snapshot
BEFORE INSERT ON order_detail_toppings
FOR EACH ROW EXECUTE FUNCTION fn_fill_order_topping_snapshot();

-- Add topping value to detail line total and recalculate parent order.
CREATE OR REPLACE FUNCTION fn_recalculate_detail_after_topping()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
    v_detail_id BIGINT;
    v_order_id BIGINT;
    v_base NUMERIC(12,2);
    v_size NUMERIC(12,2);
    v_qty INTEGER;
    v_topping_total NUMERIC(12,2);
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_detail_id := OLD.order_detail_id;
    ELSE
        v_detail_id := NEW.order_detail_id;
    END IF;

    SELECT order_id, base_price_snapshot, size_price_snapshot, quantity
      INTO v_order_id, v_base, v_size, v_qty
      FROM order_details
     WHERE order_detail_id = v_detail_id;

    IF NOT FOUND THEN
        IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
    END IF;

    SELECT COALESCE(SUM(quantity * price_snapshot),0)
      INTO v_topping_total
      FROM order_detail_toppings
     WHERE order_detail_id = v_detail_id;

    UPDATE order_details
       SET line_total = (v_base + v_size + v_topping_total) * v_qty
     WHERE order_detail_id = v_detail_id;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;

CREATE TRIGGER trg_topping_recalculate
AFTER INSERT OR UPDATE OR DELETE ON order_detail_toppings
FOR EACH ROW EXECUTE FUNCTION fn_recalculate_detail_after_topping();

-- -------------------------
-- 14. PROMOTION VALIDATION / APPLY
-- -------------------------

CREATE OR REPLACE FUNCTION fn_apply_promotion(
    p_order_id BIGINT,
    p_promo_code VARCHAR
)
RETURNS NUMERIC(12,2) LANGUAGE plpgsql AS $$
DECLARE
    v_order orders%ROWTYPE;
    v_promo promotions%ROWTYPE;
    v_discount NUMERIC(12,2);
BEGIN
    SELECT * INTO v_order FROM orders
     WHERE order_id = p_order_id FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'Order không tồn tại'; END IF;
    IF v_order.order_status <> 'Chờ thanh toán' THEN
        RAISE EXCEPTION 'Chỉ áp dụng khuyến mãi cho order chờ thanh toán';
    END IF;

    SELECT * INTO v_promo FROM promotions
     WHERE upper(promo_code) = upper(p_promo_code)
       AND is_active = TRUE
       AND CURRENT_DATE BETWEEN start_date AND end_date
     FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'Mã khuyến mãi không hợp lệ/hết hạn'; END IF;
    IF v_order.subtotal_amount < v_promo.min_order_value THEN
        RAISE EXCEPTION 'Order chưa đạt giá trị tối thiểu để áp dụng mã';
    END IF;
    IF v_promo.usage_limit IS NOT NULL AND v_promo.used_count >= v_promo.usage_limit THEN
        RAISE EXCEPTION 'Mã khuyến mãi đã hết lượt sử dụng';
    END IF;

    IF v_promo.discount_type = 'PERCENT' THEN
        v_discount := v_order.subtotal_amount * v_promo.discount_value / 100;
        IF v_promo.max_discount IS NOT NULL THEN
            v_discount := LEAST(v_discount, v_promo.max_discount);
        END IF;
    ELSE
        v_discount := v_promo.discount_value;
    END IF;

    v_discount := LEAST(v_discount, v_order.subtotal_amount);

    UPDATE orders
       SET promotion_id = v_promo.promotion_id,
           discount_amount = v_discount,
           total_amount = GREATEST(subtotal_amount - v_discount,0)
     WHERE order_id = p_order_id;

    RETURN v_discount;
END;
$$;

-- -------------------------
-- 15. REDEEM CUSTOMER POINTS
-- -------------------------
-- The report does not specify the conversion rate from points to VND.
-- Therefore this function receives the discount amount explicitly from
-- the application; it validates and records the points transaction.

CREATE OR REPLACE FUNCTION fn_redeem_customer_points(
    p_order_id BIGINT,
    p_points INTEGER,
    p_discount_amount NUMERIC(12,2),
    p_staff_id BIGINT DEFAULT NULL
)
RETURNS VOID LANGUAGE plpgsql AS $$
DECLARE
    v_customer_id BIGINT;
    v_status VARCHAR(30);
BEGIN
    IF p_points <= 0 OR p_discount_amount <= 0 THEN
        RAISE EXCEPTION 'Điểm đổi và số tiền giảm phải lớn hơn 0';
    END IF;

    SELECT customer_id, order_status INTO v_customer_id, v_status
      FROM orders WHERE order_id = p_order_id FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'Order không tồn tại'; END IF;
    IF v_status <> 'Chờ thanh toán' THEN
        RAISE EXCEPTION 'Order không còn ở trạng thái chờ thanh toán';
    END IF;
    IF v_customer_id IS NULL THEN
        RAISE EXCEPTION 'Order chưa gắn khách hàng thành viên';
    END IF;

    UPDATE customers
       SET points = points - p_points
     WHERE customer_id = v_customer_id
       AND points >= p_points;

    IF NOT FOUND THEN RAISE EXCEPTION 'Khách hàng không đủ điểm'; END IF;

    UPDATE orders
       SET points_redeemed = points_redeemed + p_points,
           discount_amount = discount_amount + p_discount_amount,
           total_amount = GREATEST(subtotal_amount - discount_amount - p_discount_amount,0)
     WHERE order_id = p_order_id;

    INSERT INTO loyalty_transactions
        (customer_id, order_id, transaction_type, points_change, description, created_by)
    VALUES
        (v_customer_id, p_order_id, 'REDEEM', -p_points,
         'Đổi điểm giảm giá cho đơn hàng', p_staff_id);
END;
$$;

-- -------------------------
-- 16. POST STOCK IMPORT / WASTE DOCUMENT
-- -------------------------
-- Call inside a transaction. A document can only be posted once.
-- IMPORT adds stock; WASTE subtracts stock.

CREATE OR REPLACE FUNCTION fn_post_stock_document(p_import_id BIGINT)
RETURNS VOID LANGUAGE plpgsql AS $$
DECLARE
    v_doc stock_imports%ROWTYPE;
    v_line RECORD;
BEGIN
    SELECT * INTO v_doc FROM stock_imports
     WHERE import_id = p_import_id FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu kho'; END IF;
    IF v_doc.status <> 'Nháp' THEN
        RAISE EXCEPTION 'Phiếu kho không ở trạng thái Nháp hoặc đã được xử lý';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM stock_import_details WHERE import_id = p_import_id) THEN
        RAISE EXCEPTION 'Phiếu kho chưa có chi tiết nguyên liệu';
    END IF;

    FOR v_line IN
        SELECT ingredient_id, quantity, unit_price
          FROM stock_import_details
         WHERE import_id = p_import_id
         ORDER BY ingredient_id
    LOOP
        IF v_doc.voucher_type = 'IMPORT' THEN
            UPDATE ingredients
               SET stock_quantity = stock_quantity + v_line.quantity
             WHERE ingredient_id = v_line.ingredient_id;

            INSERT INTO stock_movements
                (ingredient_id, movement_type, quantity_change,
                 reference_type, reference_id, note)
            VALUES
                (v_line.ingredient_id, 'IMPORT', v_line.quantity,
                 'stock_imports', p_import_id, v_doc.note);
        ELSE
            UPDATE ingredients
               SET stock_quantity = stock_quantity - v_line.quantity
             WHERE ingredient_id = v_line.ingredient_id
               AND stock_quantity >= v_line.quantity;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Không đủ tồn kho nguyên liệu ID % để xuất hủy',
                    v_line.ingredient_id;
            END IF;

            INSERT INTO stock_movements
                (ingredient_id, movement_type, quantity_change,
                 reference_type, reference_id, note)
            VALUES
                (v_line.ingredient_id, 'WASTE', -v_line.quantity,
                 'stock_imports', p_import_id, v_doc.note);
        END IF;
    END LOOP;

    UPDATE stock_imports
       SET total_cost = (
            SELECT COALESCE(SUM(quantity * unit_price),0)
              FROM stock_import_details WHERE import_id = p_import_id
           ),
           status = 'Hoàn thành',
           posted_at = CURRENT_TIMESTAMP
     WHERE import_id = p_import_id;
END;
$$;

-- -------------------------
-- 17. COMPLETE PAYMENT AND CONSUME STOCK
-- -------------------------
-- Atomic operation:
--   1. Lock order
--   2. Validate status and amount
--   3. Deduct ingredients based on drink recipes + topping recipes
--   4. Record stock movements
--   5. Insert payment
--   6. Change order status
-- Any exception rolls back the whole transaction.
--
-- points_to_earn defaults to 0 because the report does not specify
-- the points conversion policy. Configure this in the application.

CREATE OR REPLACE FUNCTION fn_complete_order_payment(
    p_order_id BIGINT,
    p_payment_method VARCHAR(30),
    p_amount_paid NUMERIC(12,2),
    p_points_to_earn INTEGER DEFAULT 0,
    p_transaction_ref VARCHAR(150) DEFAULT NULL
)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE
    v_order orders%ROWTYPE;
    v_payment_id BIGINT;
    v_need RECORD;
BEGIN
    SELECT * INTO v_order
      FROM orders
     WHERE order_id = p_order_id
     FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy đơn hàng'; END IF;
    IF v_order.order_status <> 'Chờ thanh toán' THEN
        RAISE EXCEPTION 'Đơn hàng không ở trạng thái Chờ thanh toán';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM order_details WHERE order_id = p_order_id) THEN
        RAISE EXCEPTION 'Đơn hàng chưa có món';
    END IF;
    IF p_payment_method NOT IN ('Tiền mặt','Chuyển khoản QR') THEN
        RAISE EXCEPTION 'Phương thức thanh toán không hợp lệ';
    END IF;
    IF p_amount_paid < v_order.total_amount THEN
        RAISE EXCEPTION 'Số tiền khách trả nhỏ hơn tổng tiền phải thanh toán';
    END IF;
    IF p_points_to_earn < 0 THEN
        RAISE EXCEPTION 'Điểm cộng không được âm';
    END IF;

    -- Every ordered drink must have a recipe for its selected size.
    IF EXISTS (
        SELECT 1
          FROM order_details od
         WHERE od.order_id = p_order_id
           AND NOT EXISTS (
               SELECT 1 FROM recipes r
                WHERE r.product_id = od.product_id
                  AND r.size_id = od.size_id
                  AND r.topping_id IS NULL
           )
    ) THEN
        RAISE EXCEPTION 'Có món chưa được khai báo công thức định lượng cho size đã chọn';
    END IF;

    -- Every selected topping must have an inventory recipe.
    IF EXISTS (
        SELECT 1
          FROM order_details od
          JOIN order_detail_toppings odt ON odt.order_detail_id = od.order_detail_id
         WHERE od.order_id = p_order_id
           AND NOT EXISTS (
               SELECT 1 FROM recipes r
                WHERE r.topping_id = odt.topping_id
                  AND r.product_id IS NULL
           )
    ) THEN
        RAISE EXCEPTION 'Có topping chưa được khai báo công thức định lượng';
    END IF;

    -- Aggregate ingredient usage for drink recipes and selected toppings.
    FOR v_need IN
        SELECT r.ingredient_id,
               SUM(r.quantity_required * od.quantity)::NUMERIC(14,3) AS qty_needed
          FROM order_details od
          JOIN recipes r
            ON r.product_id = od.product_id
           AND r.size_id = od.size_id
           AND r.topping_id IS NULL
         WHERE od.order_id = p_order_id
         GROUP BY r.ingredient_id

        UNION ALL

        SELECT r.ingredient_id,
               SUM(r.quantity_required * od.quantity * odt.quantity)::NUMERIC(14,3) AS qty_needed
          FROM order_details od
          JOIN order_detail_toppings odt
            ON odt.order_detail_id = od.order_detail_id
          JOIN recipes r
            ON r.topping_id = odt.topping_id
           AND r.product_id IS NULL
         WHERE od.order_id = p_order_id
         GROUP BY r.ingredient_id
    LOOP
        -- The same ingredient can be required by both drink and topping;
        -- subtracting separate rows is safe because each update locks row.
        UPDATE ingredients
           SET stock_quantity = stock_quantity - v_need.qty_needed
         WHERE ingredient_id = v_need.ingredient_id
           AND stock_quantity >= v_need.qty_needed;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Không đủ tồn kho nguyên liệu ID % (cần %)',
                v_need.ingredient_id, v_need.qty_needed;
        END IF;

        INSERT INTO stock_movements
            (ingredient_id, movement_type, quantity_change,
             reference_type, reference_id, note)
        VALUES
            (v_need.ingredient_id, 'SALE', -v_need.qty_needed,
             'orders', p_order_id, 'Trừ kho do thanh toán đơn hàng');
    END LOOP;

    INSERT INTO payments
        (order_id, payment_method, amount_paid, cash_received, change_amount,
         transaction_ref, payment_status)
    VALUES
        (p_order_id, p_payment_method, v_order.total_amount,
         CASE WHEN p_payment_method = 'Tiền mặt' THEN p_amount_paid ELSE NULL END,
         CASE WHEN p_payment_method = 'Tiền mặt'
              THEN p_amount_paid - v_order.total_amount ELSE 0 END,
         p_transaction_ref, 'SUCCESS')
    RETURNING payment_id INTO v_payment_id;

    UPDATE orders
       SET order_status = 'Đã thanh toán'
     WHERE order_id = p_order_id;

    -- Promotion usage is counted only after successful payment.
    IF v_order.promotion_id IS NOT NULL THEN
        UPDATE promotions
           SET used_count = used_count + 1
         WHERE promotion_id = v_order.promotion_id;
    END IF;

    -- Optional points award. Policy/rate is configured by application.
    IF p_points_to_earn > 0 AND v_order.customer_id IS NOT NULL THEN
        UPDATE customers
           SET points = points + p_points_to_earn
         WHERE customer_id = v_order.customer_id;

        INSERT INTO loyalty_transactions
            (customer_id, order_id, transaction_type, points_change, description)
        VALUES
            (v_order.customer_id, p_order_id, 'EARN', p_points_to_earn,
             'Tích điểm từ đơn hàng đã thanh toán');
    END IF;

    RETURN v_payment_id;
END;
$$;

-- -------------------------
-- 18. CANCEL UNPAID ORDER
-- -------------------------

CREATE OR REPLACE FUNCTION fn_cancel_unpaid_order(p_order_id BIGINT, p_reason TEXT DEFAULT NULL)
RETURNS VOID LANGUAGE plpgsql AS $$
BEGIN
    UPDATE orders
       SET order_status = 'Đã hủy',
           note = concat_ws(E'\n', note, 'Lý do hủy: ' || COALESCE(p_reason,'Không nêu'))
     WHERE order_id = p_order_id
       AND order_status = 'Chờ thanh toán';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Không thể hủy: đơn không tồn tại hoặc đã thanh toán';
    END IF;
END;
$$;

-- -------------------------
-- 19. LOYALTY POINT ADJUSTMENT
-- -------------------------

CREATE OR REPLACE FUNCTION fn_adjust_customer_points(
    p_customer_id BIGINT,
    p_points_change INTEGER,
    p_description TEXT,
    p_staff_id BIGINT DEFAULT NULL
)
RETURNS VOID LANGUAGE plpgsql AS $$
BEGIN
    IF p_points_change = 0 THEN RAISE EXCEPTION 'Số điểm thay đổi không được bằng 0'; END IF;

    UPDATE customers
       SET points = points + p_points_change
     WHERE customer_id = p_customer_id
       AND points + p_points_change >= 0;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Không tìm thấy khách hàng hoặc số điểm sau điều chỉnh không hợp lệ';
    END IF;

    INSERT INTO loyalty_transactions
        (customer_id, transaction_type, points_change, description, created_by)
    VALUES
        (p_customer_id, 'ADJUST', p_points_change, p_description, p_staff_id);
END;
$$;

-- -------------------------
-- 20. APPROVAL DECISION
-- -------------------------

CREATE OR REPLACE FUNCTION fn_resolve_approval(
    p_request_id BIGINT,
    p_owner_staff_id BIGINT,
    p_approved BOOLEAN,
    p_note TEXT DEFAULT NULL
)
RETURNS VOID LANGUAGE plpgsql AS $$
BEGIN
    UPDATE approval_requests
       SET approved_by = p_owner_staff_id,
           status = CASE WHEN p_approved THEN 'Đã duyệt' ELSE 'Từ chối' END,
           resolved_at = CURRENT_TIMESTAMP,
           resolution_note = p_note
     WHERE request_id = p_request_id
       AND status = 'Chờ duyệt';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Yêu cầu không tồn tại hoặc đã được xử lý';
    END IF;
END;
$$;

-- -------------------------
-- 21. REPORTING VIEWS
-- -------------------------

CREATE OR REPLACE VIEW vw_daily_revenue AS
SELECT
    DATE(p.paid_at) AS revenue_date,
    COUNT(*) AS paid_orders,
    SUM(p.amount_paid) AS gross_collected,
    SUM(o.discount_amount) AS total_discount,
    SUM(o.total_amount) AS net_revenue
FROM payments p
JOIN orders o ON o.order_id = p.order_id
WHERE p.payment_status = 'SUCCESS'
  AND o.order_status <> 'Đã hủy'
GROUP BY DATE(p.paid_at);

CREATE OR REPLACE VIEW vw_best_selling_products AS
SELECT
    od.product_id,
    od.product_name_snapshot AS product_name,
    SUM(od.quantity) AS quantity_sold,
    SUM(od.line_total) AS revenue
FROM order_details od
JOIN orders o ON o.order_id = od.order_id
JOIN payments p ON p.order_id = o.order_id AND p.payment_status = 'SUCCESS'
GROUP BY od.product_id, od.product_name_snapshot;

CREATE OR REPLACE VIEW vw_low_stock_ingredients AS
SELECT
    ingredient_id, ingredient_name, unit, stock_quantity, min_threshold,
    (min_threshold - stock_quantity) AS shortage_quantity
FROM ingredients
WHERE stock_quantity <= min_threshold
  AND is_active = TRUE;

CREATE OR REPLACE VIEW vw_inventory_movement_summary AS
SELECT
    i.ingredient_id,
    i.ingredient_name,
    i.unit,
    COALESCE(SUM(CASE WHEN sm.quantity_change > 0 THEN sm.quantity_change ELSE 0 END),0) AS total_in,
    COALESCE(SUM(CASE WHEN sm.quantity_change < 0 THEN -sm.quantity_change ELSE 0 END),0) AS total_out,
    i.stock_quantity AS current_stock
FROM ingredients i
LEFT JOIN stock_movements sm ON sm.ingredient_id = i.ingredient_id
GROUP BY i.ingredient_id, i.ingredient_name, i.unit, i.stock_quantity;

CREATE OR REPLACE VIEW vw_staff_work_hours AS
SELECT
    s.staff_id,
    s.full_name,
    COUNT(a.attendance_id) AS attended_shifts,
    COALESCE(SUM(EXTRACT(EPOCH FROM (a.check_out - a.check_in))/3600),0)::NUMERIC(10,2)
        AS total_work_hours
FROM staff s
LEFT JOIN attendances a ON a.staff_id = s.staff_id
GROUP BY s.staff_id, s.full_name;

